changeSet.sql:
CREATE TABLE nexus.embedding_models (
    embedding_model TEXT    NOT NULL,
    dimension       INTEGER NOT NULL,
    provider        TEXT    NOT NULL,
    CONSTRAINT embedding_models_pk PRIMARY KEY (embedding_model)
);

CREATE TABLE nexus.embedding_profile (
    tenant_id       TEXT    NOT NULL,
    content_type    TEXT    NOT NULL,
    embedding_model TEXT    NOT NULL,
    dimension       INTEGER NOT NULL,
    CONSTRAINT embedding_profile_pk PRIMARY KEY (tenant_id, content_type),
    CONSTRAINT embedding_profile_model_fk FOREIGN KEY (embedding_model)
        REFERENCES nexus.embedding_models (embedding_model)
);

ALTER TABLE nexus.embedding_profile ENABLE ROW LEVEL SECURITY;
ALTER TABLE nexus.embedding_profile FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON nexus.embedding_profile
    USING      (tenant_id = current_setting('nexus.tenant', true))
    WITH CHECK (tenant_id = current_setting('nexus.tenant', true));

changeSet.rollback:
DROP POLICY IF EXISTS tenant_isolation ON nexus.embedding_profile;
ALTER TABLE nexus.embedding_profile NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.embedding_profile DISABLE ROW LEVEL SECURITY;
DROP TABLE IF EXISTS nexus.embedding_profile CASCADE;

changeSet.sql:
ALTER TABLE nexus.catalog_collections
    ADD COLUMN dimension INTEGER,
    ADD COLUMN lifecycle_state TEXT;
